108	                lastWithShare = i;
109	                if (cuts.get(i).signum() != 0
110	                        && (smallest < 0 || cuts.get(i).compareTo(cuts.get(smallest)) <= 0)) {
111	                    smallest = i;
112	                }
113	            }
114	            int to = smallest >= 0 ? smallest : lastWithShare;
115	            cuts.set(to, cuts.get(to).add(remainder));
116	            return cuts;
117	        }
118	    }
119	
120	    private final PoolRepository pools;
121	    private final PoolMemberRepository members;
122	    private final PersonRepository people;
123	    private final SheetService sheets;
124	    private final SheetRepository sheetStore;
125	    private final Audit audit;
126	    private final SheetHistory history;
127	    private final CrewRepository crews;
128	    private final CrewMemberRepository crewMembers;
129	    private final PeriodRepository periods;
130	
131	    public PoolService(PoolRepository pools, PoolMemberRepository members, PersonRepository people,
132	            SheetService sheets, SheetRepository sheetStore, Audit audit, SheetHistory history, CrewRepository crews,
133	            CrewMemberRepository crewMembers, PeriodRepository periods) {
134	        this.periods = periods;
135	        this.history = history;
136	        this.crews = crews;
137	        this.crewMembers = crewMembers;
138	        this.pools = pools;
139	        this.members = members;
140	        this.people = people;
141	        this.sheets = sheets;
142	        this.sheetStore = sheetStore;
143	        this.audit = audit;
144	    }
145	
146	    /** The sheet's pools, in the order they were added, each with its members and its pot; then each crew, in the
147	     *  order they were added, as a pool under its name (see {@link #crewMembers}). */
148	    @Transactional(readOnly = true)
149	    public List<PoolWithMembers> list(String sheetId) {
150	        return list(sheetId, null);
151	    }
152	
153	    /** The sheet's pools as {@link #list(String)}, with {@code on} (null: the sheet's today) standing in for the
154	     *  sheet's today, as a sheet shown as of a date reads them: then the pot and the people (retired or held) are as
155	     *  they stood at the end of that date (see {@link SheetHistory}), a person not on the sheet by then is no member,
156	     *  and the pools are as they are now, each with its memberships as they stood then when the state kept them (so a
157	     *  membership since moved by a merge counts for the person who held it then), else as they are now. */
158	    @Transactional(readOnly = true)
159	    public List<PoolWithMembers> list(String sheetId, LocalDate on) {
160	        Optional<SheetState> then = on == null ? Optional.empty() : history.asOf(sheetId, on);
161	        BigDecimal sheetPot = on != null ? then.map(SheetState::pot).orElse(null)
162	                : sheetStore.findById(sheetId).map(Sheet::getPot).orElse(null);
163	        LocalDate today = on != null ? on : sheetStore.findById(sheetId).map(Sheet::getToday).orElse(null);
164	        List<Person> sheetPeople = on != null ? then.map(s -> s.rebuildPeople(sheetId)).orElse(List.of())
165	                : people.findBySheetIdOrderByPositionAscIdAsc(sheetId);
166	        List<Pool> list = pools.findBySheetIdOrderByIdAsc(sheetId);
167	        Map<Long, List<PoolMember>> byPool = members.findByPoolIdInOrderByIdAsc(list.stream().map(Pool::getId).toList())
168	                .stream().collect(Collectors.groupingBy(PoolMember::getPoolId));
169	        if (then.isPresent() && then.get().pools() != null) {
170	            byPool = new HashMap<>(byPool);
171	            for (SheetState.PoolState p : then.get().pools()) {
172	                byPool.put(p.id(), membersOf(p));
173	            }
174	        }
175	        List<Crew> sheetCrews = crews.findBySheetIdOrderByIdAsc(sheetId);
176	        Map<Long, List<CrewMember>> byCrew = crewMembers.findByCrewIdInOrderByIdAsc(
177	                sheetCrews.stream().map(Crew::getId).toList()).stream()
178	                .collect(Collectors.groupingBy(CrewMember::getCrewId));
179	        return build(sheetId, list, byPool, sheetCrews, byCrew, sheetPeople, sheetPot, today);
180	    }
181	
182	    /** The sheet's pools as they stood at the end of a date, that date standing in for the sheet's today: the pools,
183	     *  their memberships, the crews, the pot and the people all as they were then (see {@link SheetHistory}); none
184	     *  when no change was made on the sheet by then. A state kept before pools were recorded has them as they are
185	     *  now. */
186	    @Transactional(readOnly = true)
187	    public List<PoolWithMembers> stoodOn(String sheetId, LocalDate date) {
188	        Optional<SheetState> then = history.asOf(sheetId, date);
189	        if (then.isEmpty()) {
190	            return List.of();
191	        }
192	        SheetState state = then.get();
193	        if (state.pools() == null || state.crews() == null) {
194	            return list(sheetId, date);
195	        }
196	        List<Pool> list = new ArrayList<>();
197	        Map<Long, List<PoolMember>> byPool = new HashMap<>();
198	        for (SheetState.PoolState p : state.pools()) {
199	            list.add(Pool.rebuilt(sheetId, p.id(), p.name()));
200	            byPool.put(p.id(), membersOf(p));
201	        }
202	        List<Crew> sheetCrews = new ArrayList<>();
203	        Map<Long, List<CrewMember>> byCrew = new HashMap<>();
204	        for (SheetState.CrewState c : state.crews()) {
205	            sheetCrews.add(Crew.rebuilt(sheetId, c.id(), c.name(), c.leadId()));
206	            byCrew.put(c.id(), c.members().stream().map(id -> new CrewMember(c.id(), id)).toList());
207	        }
208	        return build(sheetId, list, byPool, sheetCrews, byCrew, state.rebuildPeople(sheetId), state.pot(), date);
209	    }
210	
211	    /** A kept pool's memberships, rebuilt unsaved in the order they were added. */
212	    private static List<PoolMember> membersOf(SheetState.PoolState p) {
213	        return p.members().stream().map(m -> {
214	            PoolMember member = m.memberPoolId() != null ? PoolMember.ofPool(p.id(), m.memberPoolId(), m.share())
215	                    : new PoolMember(p.id(), m.personId(), m.share());
216	            member.setDates(m.from(), m.to());
217	            return member;
218	        }).toList();
219	    }
220	
221	    /** A member's cut at the end of a period: the period's name and the cut (null: none). */
222	    public record PeriodCut(String period, BigDecimal cut) {
223	    }
224	
225	    /** A pool with, for each of its members in their order, the member's cut at the end of each period whose to-date
226	     *  is on or before the sheet's today, in the order of the periods' from-dates. */
227	    public record PoolWithHistory(PoolWithMembers pool, List<List<PeriodCut>> periodCuts) {
228	    }
229	
230	    /** The sheet's pools as {@link #list(String, LocalDate)}, each member with its cut as it stood at the end of
231	     *  each period whose to-date is on or before the sheet's today (or {@code on}): the pool, its members, the pot and
232	     *  the holds as they were then, with that day as the sheet's today (see {@link #stoodOn}); none when the member
233	     *  was not in the pool then, the pool showed no cuts or the membership was not in force on that day. */
234	    @Transactional(readOnly = true)
235	    public List<PoolWithHistory> listWithHistory(String sheetId, LocalDate on) {
236	        List<PoolWithMembers> now = list(sheetId, on);
237	        LocalDate today = on != null ? on : sheetStore.findById(sheetId).map(Sheet::getToday).orElse(null);
238	        List<Map.Entry<String, LocalDate>> ended = new ArrayList<>();
239	        if (today != null) {
240	            if (on != null) {
241	                history.viewsAsOf(sheetId, on).periods().stream().filter(p -> !p.to().isAfter(today))
242	                        .sorted(Comparator.comparing(PeriodView::from))
243	                        .forEach(p -> ended.add(Map.entry(p.name(), p.to())));
244	            } else {
245	                periods.findBySheetIdOrderByFromDateAsc(sheetId).stream().filter(p -> !p.getToDate().isAfter(today))
246	                        .forEach(p -> ended.add(Map.entry(p.getName(), p.getToDate())));
247	            }
248	        }
249	        // Each ended period's cuts, by pool id then by member key.
250	        List<Map<Long, Map<String, BigDecimal>>> cutsThen = new ArrayList<>();
251	        Map<LocalDate, Map<Long, Map<String, BigDecimal>>> byDay = new HashMap<>();
252	        for (Map.Entry<String, LocalDate> period : ended) {
253	            cutsThen.add(byDay.computeIfAbsent(period.getValue(), day -> cutsOf(stoodOn(sheetId, day))));
254	        }
255	        return now.stream().map(p -> new PoolWithHistory(p, p.members().stream().map(m -> {
256	            List<PeriodCut> cuts = new ArrayList<>();
257	            for (int i = 0; i < ended.size(); i++) {
258	                cuts.add(new PeriodCut(ended.get(i).getKey(),
259	                        cutsThen.get(i).getOrDefault(p.pool().getId(), Map.of()).get(keyOf(m))));
260	            }
261	            return cuts;
262	        }).toList())).toList();
263	    }
264	
265	    /** Each pool's shown cuts, by pool id then by member key; a member with no cut shown is left out. */
266	    private static Map<Long, Map<String, BigDecimal>> cutsOf(List<PoolWithMembers> list) {
267	        Map<Long, Map<String, BigDecimal>> made = new HashMap<>();
268	        for (PoolWithMembers p : list) {
269	            List<BigDecimal> cuts = p.cuts();
270	            Map<String, BigDecimal> of = new HashMap<>();
271	            for (int i = 0; cuts != null && i < p.members().size(); i++) {
272	                Member m = p.members().get(i);
273	                if (cuts.get(i) != null && m.inForce()) {
274	                    of.put(keyOf(m), cuts.get(i));
275	                }
276	            }
277	            made.put(p.pool().getId(), of);
278	        }
279	        return made;
280	    }
281	
282	    /** A member's key within its pool: the person's id, or pool-id for a pool. */
283	    private static String keyOf(Member m) {
284	        return m.pool() != null ? "pool-" + m.pool().getId() : String.valueOf(m.person().getId());
285	    }
286	
287	    /** The pools with their members and pots, from the stored pools and memberships, the crews, the people (one not
288	     *  among them is no member), the sheet's pot and the day standing in for the sheet's today. */
289	    private static List<PoolWithMembers> build(String sheetId, List<Pool> list, Map<Long, List<PoolMember>> byPool,
290	            List<Crew> sheetCrews, Map<Long, List<CrewMember>> byCrew, List<Person> sheetPeople,
291	            BigDecimal sheetPot, LocalDate today) {
292	        Map<Long, Person> byId = sheetPeople.stream().collect(Collectors.toMap(Person::getId, Function.identity()));
293	        Map<Long, Pool> poolsById = new HashMap<>(list.stream().collect(Collectors.toMap(Pool::getId, Function.identity())));
294	        Map<Long, List<Member>> membersOf = new HashMap<>();
295	        Map<Long, Long> parentOf = new HashMap<>();
296	        for (Pool p : list) {
297	            List<Member> of = new ArrayList<>();
298	            for (PoolMember m : byPool.getOrDefault(p.getId(), List.of())) {
299	                if (m.getMemberPoolId() != null) {
300	                    Pool child = poolsById.get(m.getMemberPoolId());
301	                    if (child != null) {
302	                        of.add(new Member(null, child, m.getShare(), false, m.getFrom(), m.getTo(),
303	                                m.inForceOn(today)));
304	                        parentOf.put(child.getId(), p.getId());
305	                    }
306	                } else if (byId.containsKey(m.getPersonId())) {
307	                    Person person = byId.get(m.getPersonId());
308	                    of.add(new Member(person, null, m.getShare(), person.heldOn(today), m.getFrom(),
309	                            m.getTo(), m.inForceOn(today)));
310	                }
311	            }
312	            membersOf.put(p.getId(), of);
313	        }
314	        list = new ArrayList<>(list);
315	        for (Crew c : sheetCrews) {
316	            Pool crewPool = Pool.ofCrew(sheetId, c.getId(), c.getName());
317	            List<Person> crewPeople = new ArrayList<>();
318	            if (c.getLeadId() != null && byId.containsKey(c.getLeadId())) {
319	                crewPeople.add(byId.get(c.getLeadId()));
320	            }
321	            for (CrewMember m : byCrew.getOrDefault(c.getId(), List.of())) {
322	                if (byId.containsKey(m.getPersonId())) {
323	                    crewPeople.add(byId.get(m.getPersonId()));
324	                }
325	            }
326	            list.add(crewPool);
327	            poolsById.put(crewPool.getId(), crewPool);
328	            membersOf.put(crewPool.getId(), crewMembers(crewPeople, today));
329	        }
330	        Map<Long, PoolWithMembers> done = new HashMap<>();
331	        return list.stream().map(p -> withPot(p.getId(), poolsById, membersOf, parentOf, sheetPot, done, 0)).toList();
332	    }
333	
334	    /** A crew's people, its lead first (when still on the sheet) then its members in the order added, as the members
335	     *  of its pool: 100.00 split equally, each share rounded half to even, with the remainder given to the lead (the
336	     *  first), each membership with no from-date or to-date. */
337	    private static List<Member> crewMembers(List<Person> crewPeople, LocalDate today) {
338	        if (crewPeople.isEmpty()) {
339	            return List.of();
340	        }
341	        BigDecimal each = FULL.divide(BigDecimal.valueOf(crewPeople.size()), 2, RoundingMode.HALF_EVEN);
342	        BigDecimal first = FULL.subtract(each.multiply(BigDecimal.valueOf(crewPeople.size() - 1)));
343	        List<Member> of = new ArrayList<>();
344	        for (int i = 0; i < crewPeople.size(); i++) {
345	            Person person = crewPeople.get(i);
346	            of.add(new Member(person, null, i == 0 ? first : each, person.heldOn(today), null, null, true));
347	        }
348	        return of;
349	    }
350	
351	    /** The pool with its members and its pot: the sheet's pot when it is a member of none, else its cut in the pool
352	     *  above (none when that pool shows no cuts or its membership there is not in force on the sheet's today). */
353	    private static PoolWithMembers withPot(Long poolId, Map<Long, Pool> poolsById, Map<Long, List<Member>> membersOf,
354	            Map<Long, Long> parentOf, BigDecimal sheetPot, Map<Long, PoolWithMembers> done, int depth) {
355	        PoolWithMembers known = done.get(poolId);
356	        if (known != null) {
357	            return known;
358	        }
359	        Long parentId = parentOf.get(poolId);
360	        BigDecimal pot = sheetPot;
361	        if (parentId != null) {
362	            pot = null;
363	            if (depth <= poolsById.size()) {
364	                PoolWithMembers parent = withPot(parentId, poolsById, membersOf, parentOf, sheetPot, done, depth + 1);
365	                List<BigDecimal> cuts = parent.cuts();
366	                if (cuts != null) {
367	                    for (int i = 0; i < parent.members().size(); i++) {
368	                        Member member = parent.members().get(i);
369	                        if (member.pool() != null && member.pool().getId().equals(poolId) && member.inForce()) {
370	                            pot = cuts.get(i);
371	                        }
372	                    }
373	                }
374	            }
375	        }
376	        PoolWithMembers made = new PoolWithMembers(poolsById.get(poolId), membersOf.get(poolId), pot);
377	        done.put(poolId, made);
378	        return made;
379	    }
380	
381	    /** Add a pool by its name, trimmed; refused when blank or already a pool or a crew on the sheet. */
382	    @Transactional
383	    public Pool add(String sheetId, String user, String name) {
384	        String key = name == null ? "" : name.strip();
385	        if (key.isEmpty()) {
386	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A pool has a name");
387	        }
388	        sheets.load(sheetId, user);
389	        sheetStore.findLockedById(sheetId).orElseThrow();
390	        if (pools.existsBySheetIdAndName(sheetId, key)) {
391	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That pool is already on the sheet");
392	        }
393	        if (crews.existsBySheetIdAndName(sheetId, key)) {
394	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That is a crew on the sheet");
395	        }
396	        Pool saved;
397	        try {
398	            saved = pools.saveAndFlush(new Pool(sheetId, key));
399	        } catch (DataIntegrityViolationException raced) {
400	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That pool is already on the sheet");
401	        }
402	        audit.recordChangeOnCommit(sheetId, user, "POOL_ADDED sheet=" + sheetId + " by=" + user
403	                + " name=" + saved.getName());
404	        return saved;
405	    }
406	
407	    /** Add a member to the pool with a share percent: a person of the sheet (personId) or another pool of it
408	     *  (memberPoolId), exactly one given. Refused when the share is not more than 0.00 and at most 100.00 with up to
409	     *  two decimals, when the person is already in it, or when the pool member is already a member of a pool, would
410	     *  contain itself through any chain, or would make a chain of pools more than three deep. The membership may
411	     *  carry a from-date and a to-date, each optional; refused when the to-date is before the from-date. */
412	    @Transactional
413	    public PoolWithMembers addMember(String sheetId, String user, long poolId, Long personId, Long memberPoolId,
414	            BigDecimal share, LocalDate from, LocalDate to) {
415	        if ((personId == null) == (memberPoolId == null)) {
416	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A member is a person or a pool");
417	        }
418	        if (share == null || share.signum() <= 0 || share.compareTo(FULL) > 0
419	                || share.stripTrailingZeros().scale() > 2) {
420	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
421	                    "A share is more than 0.00 and at most 100.00, with up to two decimals");
422	        }
423	        if (from != null && to != null && to.isBefore(from)) {
424	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A to-date is not before the from-date");
425	        }
426	        BigDecimal scaled = share.setScale(2, RoundingMode.UNNECESSARY);
427	        sheets.load(sheetId, user);
428	        sheetStore.findLockedById(sheetId).orElseThrow();
429	        Pool pool = pools.findById(poolId).filter(p -> p.getSheetId().equals(sheetId))
430	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such pool on this sheet"));
431	        String name;
432	        PoolMember member;
433	        if (personId != null) {
434	            Person person = people.findById(personId).filter(p -> p.getSheetId().equals(sheetId))
435	                    .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
436	            if (members.existsByPoolIdAndPersonId(pool.getId(), personId)) {
437	                throw new ResponseStatusException(HttpStatus.CONFLICT, "That person is already in the pool");
438	            }
439	            name = person.getName();
440	            member = new PoolMember(pool.getId(), personId, scaled);
441	        } else {
442	            Pool child = pools.findById(memberPoolId).filter(p -> p.getSheetId().equals(sheetId))
443	                    .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such pool on this sheet"));
444	            checkNesting(sheetId, pool, child);
445	            name = child.getName();
446	            member = PoolMember.ofPool(pool.getId(), child.getId(), scaled);
447	        }
448	        member.setDates(from, to);
449	        try {
450	            members.saveAndFlush(member);
451	        } catch (DataIntegrityViolationException raced) {
452	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That member is already in a pool");
453	        }
454	        audit.recordChangeOnCommit(sheetId, user, "POOL_MEMBER_ADDED sheet=" + sheetId + " by=" + user
455	                + " pool=" + pool.getName() + " name=" + name + " share=" + scaled.toPlainString() + (from == null ? "" : " from=" + from)
456	                + (to == null ? "" : " to=" + to));
457	        return list(sheetId).stream().filter(p -> p.pool().getId().equals(pool.getId())).findFirst().orElseThrow();
458	    }
459	
460	    /** Refuse making the child pool a member of the parent when it is already a member of a pool, when the parent
461	     *  is the child or within it, or when the chain of pools would be more than {@link #MAX_DEPTH} deep. */
462	    private void checkNesting(String sheetId, Pool parent, Pool child) {
463	        if (members.findByMemberPoolId(child.getId()).isPresent()) {
464	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That pool is already a member of a pool");
465	        }
466	        List<Long> ids = pools.findBySheetIdOrderByIdAsc(sheetId).stream().map(Pool::getId).toList();
467	        Map<Long, Long> parentOf = new HashMap<>();
468	        Map<Long, List<Long>> childrenOf = new HashMap<>();
469	        for (PoolMember m : members.findByPoolIdInOrderByIdAsc(ids)) {
470	            if (m.getMemberPoolId() != null) {
471	                parentOf.put(m.getMemberPoolId(), m.getPoolId());
472	                childrenOf.computeIfAbsent(m.getPoolId(), k -> new ArrayList<>()).add(m.getMemberPoolId());
473	            }
474	        }
475	        // How deep the parent sits: 1 for a pool that is a member of none.
476	        int above = 0;
477	        for (Long at = parent.getId(); at != null && above <= ids.size(); at = parentOf.get(at)) {
478	            if (at.equals(child.getId())) {
479	                throw new ResponseStatusException(HttpStatus.CONFLICT, "A pool cannot contain itself");
480	            }
481	            above++;
482	        }
483	        if (above + height(child.getId(), childrenOf, 0, ids.size()) > MAX_DEPTH) {
484	            throw new ResponseStatusException(HttpStatus.CONFLICT,
485	                    "A chain of pools is at most " + MAX_DEPTH + " deep");
486	        }
487	    }
488	
489	    /** How many pools deep the chain below a pool goes, counting the pool itself. */
490	    private static int height(Long poolId, Map<Long, List<Long>> childrenOf, int depth, int limit) {
491	        int most = 0;
492	        if (depth <= limit) {
493	            for (Long c : childrenOf.getOrDefault(poolId, List.of())) {
494	                most = Math.max(most, height(c, childrenOf, depth + 1, limit));
495	            }
496	        }
497	        return 1 + most;
498	    }
499	}
