69	        if (existing.stream().anyMatch(p -> p.getName().equals(trimmed))) {
70	            throw nameInUse();
71	        }
72	        if (existing.stream().anyMatch(p -> p.overlaps(from, to))) {
73	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period overlaps another on this sheet");
74	        }
75	        Period added;
76	        try {
77	            added = periods.saveAndFlush(new Period(sheetId, trimmed, from, to, cap));
78	        } catch (DataIntegrityViolationException raced) {
79	            throw nameInUse();
80	        }
81	        audit.recordChangeOnCommit(sheetId, user, "PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + added.getName()
82	                + " from=" + added.getFromDate() + " to=" + added.getToDate()
83	                + (added.getClaimCap() == null ? "" : " cap=" + added.getClaimCap()));
84	        return added;
85	    }
86	
87	    /** Generate one period per calendar month from the from-date's month to the to-date's month, each running
88	     *  from the first to the last day of its month and named yyyy-mm. A month whose name is already a period, or
89	     *  whose days overlap a period of the sheet, is left out. Refused when the to-date is before the from-date; with
90	     *  no from-date it starts on the sheet's today. Returns the periods made, in month order. */
91	    @Transactional
92	    public List<Period> generate(String sheetId, String user, LocalDate fromDate, LocalDate to) {
93	        sheets.load(sheetId, user);
94	        LocalDate today = sheetStore.findLockedById(sheetId).orElseThrow().getToday();
95	        LocalDate from = fromDate != null ? fromDate : today;
96	        if (to.isBefore(from)) {
97	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date cannot be before the from-date");
98	        }
99	        List<Period> existing = periods.findBySheetIdOrderByFromDateAsc(sheetId);
100	        List<Period> made = new ArrayList<>();
101	        for (YearMonth month = YearMonth.from(from); !month.isAfter(YearMonth.from(to)); month = month.plusMonths(1)) {
102	            String name = month.toString();
103	            LocalDate first = month.atDay(1);
104	            LocalDate last = month.atEndOfMonth();
105	            if (existing.stream().anyMatch(p -> p.getName().equals(name) || p.overlaps(first, last))) {
106	                continue;
107	            }
108	            Period added = periods.saveAndFlush(new Period(sheetId, name, first, last));
109	            audit.recordChangeOnCommit(sheetId, user, "PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + added.getName()
110	                    + " from=" + added.getFromDate() + " to=" + added.getToDate());
111	            made.add(added);
112	        }
113	        return made;
114	    }
115	
116	    /** Generate the twelve monthly periods of the fiscal year starting in the given calendar year, from the first of
117	     *  the sheet's fiscal start month, exactly as {@link #generate} does. Returns the periods made, in month order. */
118	    @Transactional
119	    public List<Period> generateFiscalYear(String sheetId, String user, int year) {
120	        Sheet sheet = sheets.load(sheetId, user);
121	        YearMonth first = YearMonth.of(year, sheet.getFiscalStartMonth());
122	        return generate(sheetId, user, first.atDay(1), first.plusMonths(11).atEndOfMonth());
123	    }
124	
125	    /** Roll the fiscal year starting in the given calendar year over; only a steward may, and it is refused when the
126	     *  sheet has no period in that fiscal year. The next fiscal year's twelve periods are generated exactly as
127	     *  {@link #generateFiscalYear} does, and each person's open figure at the end of the old year's last period, when not
128	     *  0.00, is added to their opening balance for the new year's first period. Returns the periods made, in month order. */
129	    @Transactional
130	    public List<Period> rollover(String sheetId, String user, int year) {
131	        sheets.load(sheetId, user);
132	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
133	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
134	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward may roll the year over");
135	        }
136	        List<Period> oldYear = periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
137	                .filter(p -> sheet.fiscalYearOf(p.getFromDate()) == year).toList();
138	        if (oldYear.isEmpty()) {
139	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That fiscal year has no periods on this sheet");
140	        }
141	        LocalDate end = oldYear.stream().map(Period::getToDate).max(Comparator.naturalOrder()).orElseThrow();
142	        Map<Long, BigDecimal> open = rollup.openByPersonAt(sheetId, oldYear, end);
143	        List<Period> made = generateFiscalYear(sheetId, user, year + 1);
144	        Period first = periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
145	                .filter(p -> sheet.fiscalYearOf(p.getFromDate()) == year + 1).findFirst()
146	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT,
147	                        "The next fiscal year has no period to carry into"));
148	        for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
149	            BigDecimal amount = open.getOrDefault(person.getId(), BigDecimal.ZERO.setScale(2));
150	            if (amount.signum() == 0) {
151	                continue;
152	            }
153	            first.addOpening(person.getId(), amount);
154	            audit.recordChangeOnCommit(sheetId, user, "OPENING_SET sheet=" + sheetId + " by=" + user + " name="
155	                    + person.getName() + " period=" + first.getName() + " amount=" + amount.toPlainString());
156	        }
157	        periods.saveAndFlush(first);
158	        audit.recordChangeOnCommit(sheetId, user, "ROLLOVER sheet=" + sheetId + " by=" + user + " fy=FY" + year
159	                + " periods=" + made.size());
160	        return made;
161	    }
162	
163	    /** Generate the four calendar quarters of the given year, named yyyy-Q1 to yyyy-Q4, each running from the first
164	     *  day of its first month to the last day of its third. A quarter whose name is already a period, or whose days
165	     *  overlap a period of the sheet, is left out, as {@link #generate} does. Returns the periods made, in order. */
166	    @Transactional
167	    public List<Period> generateQuarters(String sheetId, String user, int year) {
168	        sheets.load(sheetId, user);
169	        sheetStore.findLockedById(sheetId).orElseThrow();
170	        List<Period> existing = periods.findBySheetIdOrderByFromDateAsc(sheetId);
171	        List<Period> made = new ArrayList<>();
172	        for (int quarter = 1; quarter <= 4; quarter++) {
173	            String name = year + "-Q" + quarter;
174	            YearMonth start = YearMonth.of(year, quarter * 3 - 2);
175	            LocalDate first = start.atDay(1);
176	            LocalDate last = start.plusMonths(2).atEndOfMonth();
177	            if (existing.stream().anyMatch(p -> p.getName().equals(name) || p.overlaps(first, last))) {
178	                continue;
179	            }
180	            Period added = periods.saveAndFlush(new Period(sheetId, name, first, last));
181	            audit.recordChangeOnCommit(sheetId, user, "PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + added.getName()
182	                    + " from=" + added.getFromDate() + " to=" + added.getToDate());
183	            made.add(added);
184	        }
185	        return made;
186	    }
187	
188	    /** Close a period, open or soft-closed, fixing its due-total afresh as it is now; refused for a role the
189	     *  permission matrix does not allow, and when it is already closed. The sheet is locked so no claim in it changes while its total is taken. */
190	    @Transactional
191	    public Period close(String sheetId, String user, String name) {
192	        sheets.load(sheetId, user);
193	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
194	        if (!sheet.allows("close", roles.roleOf(sheetId, user))) {
195	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not close a period");
196	        }
197	        Period period = periods.findBySheetIdAndName(sheetId, name)
198	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet"));
199	        if (period.isClosed()) {
200	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed");
201	        }
202	        return closeAndRecord(sheetId, user, period, "");
203	    }
204	
205	    /** Soft-close an open period, fixing its due-total and each person's figure for it as they are now, while its
206	     *  claims can still be changed; refused for a role the permission matrix does not allow to close, and when it is
207	     *  already closed or soft-closed. */
208	    @Transactional
209	    public Period softClose(String sheetId, String user, String name) {
210	        sheets.load(sheetId, user);
211	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
212	        if (!sheet.allows("close", roles.roleOf(sheetId, user))) {
213	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not close a period");
214	        }
215	        Period period = periods.findBySheetIdAndName(sheetId, name)
216	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet"));
217	        if (period.isClosed() || period.isSoftClosed()) {
218	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed");
219	        }
220	        period.softClose(rollup.dueByPersonBetween(sheetId, period.getFromDate(), period.getToDate()),
221	                rollup.carriedByPerson(sheetId, period));
222	        Period closed = periods.saveAndFlush(period);
223	        audit.recordChangeOnCommit(sheetId, user, "PERIOD_SOFT_CLOSED sheet=" + sheetId + " by=" + user + " period="
224	                + closed.getName() + " total=" + closed.getClosedTotal().toPlainString());
225	        return closed;
226	    }
227	
228	    /** Close, in order of their to-dates, every open period of the sheet whose to-date plus its grace days is
229	     *  before its today, each exactly as a close by hand. Called with the sheet locked, once its new today is set. */
230	    @Transactional
231	    public void closePastGrace(Sheet sheet, String user) {
232	        if (sheet.getGraceDays() == null) {
233	            return;
234	        }
235	        periods.findBySheetIdOrderByFromDateAsc(sheet.getId()).stream()
236	                .filter(p -> !p.isClosed() && !p.isSoftClosed() && sheet.pastGrace(p.getToDate()))
237	                .sorted(Comparator.comparing(Period::getToDate))
238	                .forEach(p -> closeAndRecord(sheet.getId(), user, p, " auto=yes"));
239	    }
240	
241	    /** Fix a period's due-total as it is now and record the close; the audit line ends with the suffix given. */
242	    private Period closeAndRecord(String sheetId, String user, Period period, String suffix) {
243	        period.close(rollup.dueByPersonBetween(sheetId, period.getFromDate(), period.getToDate()),
244	                rollup.carriedByPerson(sheetId, period));
245	        Period closed = periods.saveAndFlush(period);
246	        BigDecimal total = closed.getClosedTotal();
247	        audit.recordChangeOnCommit(sheetId, user, "PERIOD_CLOSED sheet=" + sheetId + " by=" + user + " period=" + closed.getName()
248	                + " total=" + total.toPlainString() + suffix);
249	        return closed;
250	    }
251	
252	    /** Reopen a closed or soft-closed period, making its due-total live again; only a role the permission matrix allows may (by
253	     *  default a steward), and it is refused when the period is open or locked. */
254	    @Transactional
255	    public Period reopen(String sheetId, String user, String name) {
256	        sheets.load(sheetId, user);
257	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
258	        if (!sheet.allows("reopen", roles.roleOf(sheetId, user))) {
259	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not reopen a period");
260	        }
261	        Period period = periods.findBySheetIdAndName(sheetId, name)
262	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet"));
263	        if (!period.isClosed() && !period.isSoftClosed()) {
264	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is not closed");
265	        }
266	        if (period.isLocked()) {
267	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is locked");
268	        }
269	        period.reopen();
270	        Period reopened = periods.saveAndFlush(period);
271	        audit.recordChangeOnCommit(sheetId, user, "PERIOD_REOPENED sheet=" + sheetId + " by=" + user + " period=" + reopened.getName());
272	        return reopened;
273	    }
274	
275	    /** Lock or unlock a period; only a steward may, and it is refused when the period is already so. */
276	    @Transactional
277	    public Period setLocked(String sheetId, String user, String name, boolean locked) {
278	        sheets.load(sheetId, user);
279	        sheetStore.findLockedById(sheetId).orElseThrow();
280	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
281	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
282	                    "Only a steward may " + (locked ? "lock" : "unlock") + " a period");
283	        }
284	        Period period = periods.findBySheetIdAndName(sheetId, name)
285	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet"));
286	        if (period.isLocked() == locked) {
287	            throw new ResponseStatusException(HttpStatus.CONFLICT,
288	                    locked ? "That period is already locked" : "That period is not locked");
289	        }
290	        period.setLocked(locked);
291	        Period saved = periods.saveAndFlush(period);
292	        audit.recordChangeOnCommit(sheetId, user, (locked ? "PERIOD_LOCKED" : "PERIOD_UNLOCKED") + " sheet=" + sheetId
293	                + " by=" + user + " period=" + saved.getName());
294	        return saved;
295	    }
296	
297	    private static ResponseStatusException nameInUse() {
298	        return new ResponseStatusException(HttpStatus.CONFLICT, "That period name is already in use on this sheet");
299	    }
300	}
